#include <stdio.h>

/* contadorDeVisitas acompanha as visitas da semana. O contador nasce em 0
   e cresce tres vezes; os tres printf ja estao na ordem certa.
   Escreva, antes de cada printf, o += que acrescenta as visitas do dia. */
void contadorDeVisitas(void) {
    int visitas = 0;

    /* segunda: acrescente 12 visitas */
    printf("visitas: %d\n", visitas);

    /* terca: acrescente 7 visitas */
    printf("visitas: %d\n", visitas);

    /* quarta: acrescente 23 visitas */
    printf("visitas: %d\n", visitas);
}

