#include <stdio.h>

/* teste do desafio contador-de-visitas — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste (modelo cenario-do-harness):
   freopen manda o stdout para o arquivo temporario, o teste chama a funcao
   do aluno e le o arquivo de volta — stdlib puro, sem runner proprio. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void contadorDeVisitas(void);

SM_TEST(o_total_de_cada_dia) {
    /* captura: o stdout vira o arquivo sm_saida.tmp */
    freopen("sm_saida.tmp", "w", stdout);
    contadorDeVisitas();
    fflush(stdout);

    /* leitura linha a linha: uma linha por dia, na ordem da semana */
    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o total da segunda", linha, "visitas: 12\n",
              "o contador nasce em 0 e a segunda acrescenta 12");
    fgets(linha, 80, f);
    checa_str("o total da terca", linha, "visitas: 19\n",
              "o += soma sobre o total de agora: 12 mais 7 sao 19");
    fgets(linha, 80, f);
    checa_str("o total da quarta", linha, "visitas: 42\n",
              "19 mais as 23 visitas da quarta sao 42");
    /* a saida TERMINA na terceira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "sao tres dias: nenhuma quarta linha e aceita");
    fclose(f);
}

solutionCode:
#include <stdio.h>

void contadorDeVisitas(void) {
    int visitas = 0;
    visitas += 12;
    printf("visitas: %d\n", visitas);
    visitas += 7;
    printf("visitas: %d\n", visitas);
    visitas += 23;
    printf("visitas: %d\n", visitas);
}
